from rcb_client import Robot
import numpy as np
r=Robot();o=r.get_obs(depth=True,video='none'); p=o.meta['proprio']['now']; print('now tcp',p[8:15], 'joints',p[:7])
def point(cam,u,v):
 d=o.last_depth[cam]; E=np.asarray(o.meta['cameras'][cam]['extrinsic_cv']); K=np.asarray(o.meta['cameras'][cam]['intrinsic_cv']); z=np.median(d[max(0,v-2):v+3,max(0,u-2):u+3]);c=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]);return np.linalg.inv(E[:,:3])@(c-E[:,3])
for uv in [(477,136),(488,136),(500,135),(512,136),(524,136),(535,137)]:print('marker ego',uv,point('egocentric_mirrored_camera',*uv))
for uv in [(760,524),(770,518),(780,512),(790,507),(800,501),(812,496)]:print('marker shoulder',uv,point('over_shoulder_left_camera',*uv))
for uv in [(480,458),(490,445),(500,440),(510,440),(520,445),(530,455),(535,470),(520,485),(500,488),(480,475)]:print('mug rim',uv,point('over_shoulder_left_camera',*uv))
q=p[11:15].astype(float); print('orientation',q)
for xyz in [[.28,.105,.12],[.28,.105,.018],[.59,.41,.22],[.59,.41,.18],[.59,.41,.15]]:
 ans=r.ik({'tcp': [*xyz,*q]},seed=p[:7]);print('ik',xyz,ans.get('ok'),ans.get('error'),ans.get('q'))
